        const requested = challenge.credentials?.length ?? 0;
        const fulfilled = matches.length;
        const match = (requested === fulfilled);
        const response = {
            challenge: challengeDID,
            credentials: pairs,
            requested: requested,
            fulfilled: fulfilled,
            match: match
        };
