        const ownerDid = pollDoc.didDocument?.controller;
        if (!ownerDid) {
            throw new KeymasterError('poll owner not found');
        }
        const registry = this.ephemeralRegistry;
        const validUntil = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();
